namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design principles.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy."
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He previously worked at Google Research before joining academia."
        },
        new()
        {
            Id = 3, CourseCode = "CS 310", Title = "Database Systems",
            Description = "Introduction to database design, SQL, normalization, transaction processing, and modern NoSQL systems.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, IsFeatured = false,
            InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez brings industry experience from Oracle and MongoDB. Her research focuses on distributed database architectures."
        },
        new()
        {
            Id = 4, CourseCode = "MATH 151", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, IsFeatured = true,
            InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible. He has authored two popular textbooks on introductory mathematics."
        },
        new()
        {
            Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra",
            Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, IsFeatured = false,
            InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research spans applied linear algebra and numerical methods. She collaborates with the CS department on machine learning projects."
        },
        new()
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.",
            Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 1:00–3:00 PM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Alan Torres", InstructorBio = "Dr. Torres is an experimental physicist who spent a decade at CERN. He brings real-world research experience into the classroom."
        },
        new()
        {
            Id = 7, CourseCode = "PHYS 220", Title = "Electromagnetism",
            Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Prerequisite: PHYS 101 and MATH 151.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Lisa Patel", InstructorBio = "Dr. Patel is a theoretical physicist specializing in quantum electrodynamics. She has mentored dozens of undergraduate researchers."
        },
        new()
        {
            Id = 8, CourseCode = "ENG 110", Title = "Academic Writing",
            Description = "Develop skills in critical reading, argumentation, research methods, and clear academic prose. Required for all first-year students.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", DepartmentId = 4, IsFeatured = true,
            InstructorName = "Prof. David Nguyen", InstructorBio = "Prof. Nguyen is a published author and rhetoric scholar. He has directed the university writing center for over a decade."
        },
        new()
        {
            Id = 9, CourseCode = "ENG 250", Title = "American Literature",
            Description = "Survey of major American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Dr. Rachel Adams", InstructorBio = "Dr. Adams specializes in 20th-century American fiction. Her book on the Harlem Renaissance received the National Book Critics Circle Award."
        },
        new()
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "A survey of global civilizations from prehistory through the late medieval period, covering social, political, and cultural developments.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an archaeologist and historian whose fieldwork spans three continents. He brings artifacts and primary sources into every lecture."
        },
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

